head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.STD_CD_APPL_ID = "";

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description ESG채권 처리자 조회
 * @returns {void}
 * @hidden N
 */
scwin.ins_search = function() {

    let param = '';
    param += "&{P}STD_CD=" + scwin.param1; // 표준코드

    const dsNm = 'BNSSRI_PRCNM_LIST';
    const qryId = 'lds.stf.bnssri.select.sriBndMgtList.prcnm';
    $c.bns.fn_SearchBns("ULDBNS22004.xml", dts_List, dsNm, qryId, param);
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = scwin.STD_CD_APPL_ID;
    scwin.arrPar[1] = "STD_CD";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    const arrPar = new Array();
    const parentWin = $c.frame.path("../");
    const fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar !== undefined) {
        fn_GetPar(scwin.arrPar);
        scwin.param1 = ((scwin.arrPar.length >= 1) && (scwin.arrPar[0] !== undefined) ? scwin.arrPar[0] : "");
        //  param2  = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");

        scwin.ins_search();
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    // alert('dts_List.OnLoadCompleted('+rowcount+')');

};
